contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] calldata _tos, uint[] calldata v) public payable {
        require(_tos.length == v.length);
        // observe public getters before the call
        address before_from = c.from();
        address before_caddress = c.caddress();
        bool reverted;
        bool ret;
        // call transfer and capture revert
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // after-values
        address after_from = c.from();
        address after_caddress = c.caddress();
        // General rule: if the call did not revert then it must have returned true
        // and the public stored addresses remain unchanged (transfer should not modify them).
        assert(reverted || (ret == true && before_from == after_from && before_caddress == after_caddress));
    }
    receive() external payable {}
}

